$ErrorActionPreference = 'Stop'

Write-Host ''
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ' SYNRGYPRO - ADMIN DASHBOARD + IFUTS SILENT SYNC INSTALLER' -ForegroundColor Cyan
Write-Host ' STANDALONE V1' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ''

$project = 'C:\xampp\htdocs\PRO\synrcypro-laravel'
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'

if (-not (Test-Path (Join-Path $project 'artisan'))) {
    throw "Project Laravel tidak ditemukan di: $project"
}

$payload = @(
    @{ Target = 'app\Services\AdminAllDashboardLiveService.php'; Data = '' },
    @{ Target = 'app\Services\IfutsService.php'; Data = '' },
    @{ Target = 'resources\views\admin-all\dashboard.blade.php'; Data = '' },
    @{ Target = 'resources\views\admin-all\ifuts\_silent-sync.blade.php'; Data = '' }
)

foreach ($item in $payload) {
    $target = Join-Path $project $item.Target
    $targetDir = Split-Path -Parent $target

    New-Item -ItemType Directory -Force -Path $targetDir | Out-Null

    if (Test-Path $target) {
        $backup = "$target.bak-$stamp"
        Copy-Item $target $backup -Force
        Write-Host "BACKUP: $($item.Target)" -ForegroundColor DarkYellow
    }

    [System.IO.File]::WriteAllBytes(
        $target,
        [System.Convert]::FromBase64String($item.Data)
    )

    Write-Host "OK: $($item.Target)" -ForegroundColor Green
}

Write-Host ''
Write-Host 'Patch IFUTS index...' -ForegroundColor Cyan

$ifutsIndex = Join-Path $project 'resources\views\admin-all\ifuts\index.blade.php'

if (-not (Test-Path $ifutsIndex)) {
    throw "IFUTS index tidak ditemukan: $ifutsIndex"
}

Copy-Item $ifutsIndex "$ifutsIndex.bak-$stamp" -Force

$content = Get-Content $ifutsIndex -Raw

$oldMessage = '<span>{{ $ifutsIntegration[''message''] ?? ''Integrasi belum tersedia.'' }}</span>'
$newMessage = '<span>Sedang mengambil data IFUTS. Data akan muncul otomatis tanpa refresh manual.</span>'

if ($content.Contains($oldMessage)) {
    $content = $content.Replace(
        $oldMessage,
        $newMessage
    )
}

$include = "@include('admin-all.ifuts._silent-sync')"

if ($content -notmatch [regex]::Escape($include)) {
    $idx = $content.LastIndexOf('@endsection')

    if ($idx -lt 0) {
        throw 'Tidak menemukan @endsection pada IFUTS index.'
    }

    $content = $content.Insert(
        $idx,
        "$include`r`n"
    )
}

Set-Content -Path $ifutsIndex -Value $content -Encoding UTF8
Write-Host 'OK: IFUTS index silent-sync patch' -ForegroundColor Green

Write-Host ''
Write-Host 'Membersihkan cache Laravel...' -ForegroundColor Cyan

Push-Location $project

try {
    & php artisan view:clear
    & php artisan optimize:clear
}
finally {
    Pop-Location
}

Write-Host ''
Write-Host '============================================================' -ForegroundColor Green
Write-Host ' INSTALL SELESAI' -ForegroundColor Green
Write-Host '============================================================' -ForegroundColor Green
Write-Host ''
Write-Host 'Backup file lama memakai suffix:' -ForegroundColor Gray
Write-Host ".bak-$stamp" -ForegroundColor Gray
Write-Host ''
Write-Host 'Buka:' -ForegroundColor Cyan
Write-Host 'http://127.0.0.1:8000/admin-all'
Write-Host 'http://127.0.0.1:8000/admin-all/ifuts'
Write-Host ''
Write-Host 'Lalu Ctrl + F5 satu kali.' -ForegroundColor Yellow
